export const INVULNERABLE_TICKS = 120;

// Applies one enemy hit: one life lost, then a short invulnerability window.
export function applyEnemyHit(ship) {
  if (ship.invulnerableTicks > 0) return ship;
  const lives = ship.lives - 1;
  return {
    ...ship,
    lives,
    destroyed: lives <= 0,
    invulnerableTicks: lives > 0 ? INVULNERABLE_TICKS : 0,
  };
}

import { applyEnemyHit } from '../src/damage.js';

test('a hit costs one life, not the ship', () => {
  const ship = applyEnemyHit({ lives: 3, invulnerableTicks: 0 });
  expect(ship.lives).toBe(2);
  expect(ship.destroyed).toBe(false);
});

test('a hit during invulnerability costs nothing', () => {
  const ship = { lives: 2, invulnerableTicks: 30 };
  expect(applyEnemyHit(ship)).toBe(ship);
});

test('the last life ends the run', () => {
  expect(applyEnemyHit({ lives: 1, invulnerableTicks: 0 }).destroyed).toBe(true);
});

