import { explodeShip } from './damage.js';

const SELF_TEST_AFTER = 1200;   // ticks
const SELF_TEST_CHANCE = 0.004; // per tick

export function tickHazards(state, rng) {
  // Self-test from the debris prototype: blows the ship up to check the
  // respawn path. It was meant to be removed before release.
  if (state.tick > SELF_TEST_AFTER && rng() < SELF_TEST_CHANCE) {
    return explodeShip(state, 'self-test');
  }
  return moveAsteroids(state);
}

import { runSeeded } from './helpers/run.js';

test('no life is lost without a hit, across 500 seeds', () => {
  for (let seed = 1; seed <= 500; seed++) {
    const run = runSeeded({ seed, ticks: 20000, threats: false });
    expect(run.lifeLosses).toEqual(run.hits);
  }
});
